Value f_IsLetterCode(Value **cells, Value *args, int32_t count) {
    (void)cells; (void)args; (void)count;
    Value v_Code = args[0];
    (void)v_Code;
    Value v_Low = alg_int(0);
    (void)v_Low;
    Value v_High = alg_nil();
    (void)v_High;
    (void)((v_High = alg_subtract(alg_divide(alg_property(v_LETTER_RANGES, "Length"), alg_int(2)), alg_int(1))));
    while (alg_truthy(alg_less_equal(v_Low, v_High))) {
        {
            Value v_Middle = alg_divide((alg_add(v_Low, v_High)), alg_int(2));
            (void)v_Middle;
            if (alg_truthy(alg_less(v_Code, alg_subscript_get(v_LETTER_RANGES, alg_multiply(v_Middle, alg_int(2)))))) {
                (void)((v_High = alg_subtract(v_Middle, alg_int(1))));
            } else {
                if (alg_truthy(alg_greater(v_Code, alg_subscript_get(v_LETTER_RANGES, alg_add(alg_multiply(v_Middle, alg_int(2)), alg_int(1)))))) {
                    (void)((v_Low = alg_add(v_Middle, alg_int(1))));
                } else {
                    return alg_bool(true);
                }
            }
        }
    }
    return alg_bool(false);
    return alg_nil();
}

void init_Unicode(void) {
    fn_IsLetterCode = alg_closure("IsLetterCode", f_IsLetterCode, NULL, 0, 1);
    v_LETTER_RANGES = lit_0();
}
